import{_ as a,c as e,o as r,ag as o}from"./chunks/framework.CMajxlqO.js";const u=JSON.parse('{"title":"Skapa nytt projekt","description":"","frontmatter":{},"headers":[],"relativePath":"02-projektstruktur/skapa-projekt.md","filePath":"02-projektstruktur/skapa-projekt.md","lastUpdated":1768315788000}'),i={name:"02-projektstruktur/skapa-projekt.md"};function l(n,t,s,p,k,c){return r(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="skapa-nytt-projekt" tabindex="-1">Skapa nytt projekt <a class="header-anchor" href="#skapa-nytt-projekt" aria-label="Permalink to &quot;Skapa nytt projekt&quot;">​</a></h1><p>Att skapa ett nytt projekt i TIA Portal är det första steget i varje automationsprojekt. Ett projekt samlar all information om hårdvara, nätverk, program och HMI på ett ställe. Här går vi igenom hur du skapar och konfigurerar ett nytt projekt från grunden.</p><h2 id="starta-tia-portal-och-skapa-projekt" tabindex="-1">Starta TIA Portal och skapa projekt <a class="header-anchor" href="#starta-tia-portal-och-skapa-projekt" aria-label="Permalink to &quot;Starta TIA Portal och skapa projekt&quot;">​</a></h2><h3 id="steg-1-oppna-tia-portal" tabindex="-1">Steg 1: Öppna TIA Portal <a class="header-anchor" href="#steg-1-oppna-tia-portal" aria-label="Permalink to &quot;Steg 1: Öppna TIA Portal&quot;">​</a></h3><ol><li>Starta TIA Portal från Windows startmeny</li><li>Du möts av <strong>Portal View</strong> - startskärmen</li><li>Välj &quot;Create new project&quot; eller använd genvägen <code>Ctrl+N</code></li></ol><h3 id="steg-2-projektinstallningar" tabindex="-1">Steg 2: Projektinställningar <a class="header-anchor" href="#steg-2-projektinstallningar" aria-label="Permalink to &quot;Steg 2: Projektinställningar&quot;">​</a></h3><p>I dialogen för nytt projekt anger du:</p><p><strong>Projektnamn:</strong></p><ul><li>Välj ett beskrivande namn (t.ex. &quot;MittFörstaProjekt&quot; eller &quot;ConveyorSystem_2026&quot;)</li><li>Undvik specialtecken och mellanslag</li><li>Använd understreck <code>_</code> eller CamelCase</li></ul><p><strong>Projektsökväg:</strong></p><ul><li>Välj en lämplig plats på din dator</li><li>Undvik nätverksenheter (kan vara långsamt)</li><li>Rekommendation: <code>C:\\TIA_Projects\\</code></li></ul><p><strong>Författare och kommentar:</strong></p><ul><li>Fyll i ditt namn som författare</li><li>Lägg till en kort beskrivning av projektet</li><li>Detta hjälper vid dokumentation och arkivering</li></ul><h3 id="steg-3-bekrafta-och-oppna" tabindex="-1">Steg 3: Bekräfta och öppna <a class="header-anchor" href="#steg-3-bekrafta-och-oppna" aria-label="Permalink to &quot;Steg 3: Bekräfta och öppna&quot;">​</a></h3><ol><li>Klicka på &quot;Create&quot;</li><li>Projektet skapas och öppnas automatiskt</li><li>Du ser nu <strong>Project View</strong> med projektträdet till vänster</li></ol><h2 id="projektstruktur-i-tia-portal" tabindex="-1">Projektstruktur i TIA Portal <a class="header-anchor" href="#projektstruktur-i-tia-portal" aria-label="Permalink to &quot;Projektstruktur i TIA Portal&quot;">​</a></h2><p>Ett nyskapat projekt har följande grundstruktur:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MittProjekt/</span></span>
<span class="line"><span>├── Devices &amp; networks     # Hårdvarukonfiguration</span></span>
<span class="line"><span>├── PLC tags               # Globala taggar (skapas vid PLC-tillägg)</span></span>
<span class="line"><span>├── Program blocks         # Programkod (skapas vid PLC-tillägg)</span></span>
<span class="line"><span>├── HMI tags               # HMI-taggar (skapas vid HMI-tillägg)</span></span>
<span class="line"><span>├── Screens                # HMI-skärmbilder (skapas vid HMI-tillägg)</span></span>
<span class="line"><span>└── Common data            # Delad information</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>Projektträdet visas till vänster. Dubbelklicka på en post för att öppna den i arbetsytan till höger.</p></div><h2 id="projektinstallningar-och-konfiguration" tabindex="-1">Projektinställningar och konfiguration <a class="header-anchor" href="#projektinstallningar-och-konfiguration" aria-label="Permalink to &quot;Projektinställningar och konfiguration&quot;">​</a></h2><h3 id="sprak-och-enheter" tabindex="-1">Språk och enheter <a class="header-anchor" href="#sprak-och-enheter" aria-label="Permalink to &quot;Språk och enheter&quot;">​</a></h3><ol><li>Högerklicka på projektnamnet i trädet</li><li>Välj &quot;Properties&quot;</li><li>Under <strong>Language &amp; Resources</strong>: <ul><li>Välj projektspråk (svenska/engelska)</li><li>Ställ in standardenheter (metriskt/imperiellt)</li></ul></li></ol><h3 id="versionshantering" tabindex="-1">Versionshantering <a class="header-anchor" href="#versionshantering" aria-label="Permalink to &quot;Versionshantering&quot;">​</a></h3><ol><li>Under &quot;Properties&quot; → <strong>General</strong></li><li>Fyll i versionsnummer (t.ex. &quot;1.0.0&quot;)</li><li>Lägg till ändringskommentarer</li></ol><h3 id="automatisk-sakerhetskopiering" tabindex="-1">Automatisk säkerhetskopiering <a class="header-anchor" href="#automatisk-sakerhetskopiering" aria-label="Permalink to &quot;Automatisk säkerhetskopiering&quot;">​</a></h3><p>TIA Portal kan automatiskt skapa säkerhetskopior:</p><ol><li>Meny: <strong>Options</strong> → <strong>Settings</strong></li><li>Gå till <strong>General</strong> → <strong>Backup</strong></li><li>Aktivera &quot;Enable backup&quot;</li><li>Välj backup-intervall och antal kopior att behålla</li></ol><h2 id="best-practices-for-projektnamn" tabindex="-1">Best Practices för projektnamn <a class="header-anchor" href="#best-practices-for-projektnamn" aria-label="Permalink to &quot;Best Practices för projektnamn&quot;">​</a></h2><p>✅ <strong>Bra exempel:</strong></p><ul><li><code>ConveyorLine_Main_v1</code></li><li><code>PackagingMachine_2026</code></li><li><code>BuildingHVAC_FloorB</code></li></ul><p>❌ <strong>Undvik:</strong></p><ul><li><code>Test123</code> (otydligt)</li><li><code>Projekt 1</code> (mellanslag)</li><li><code>äöå-projekt</code> (specialtecken)</li><li><code>C:\\Very\\Long\\Path\\Names\\...</code> (för långa sökvägar)</li></ul><h2 id="nasta-steg" tabindex="-1">Nästa steg <a class="header-anchor" href="#nasta-steg" aria-label="Permalink to &quot;Nästa steg&quot;">​</a></h2><p>När projektet är skapat är nästa steg att:</p><ol><li><strong>Lägga till hårdvara</strong> - PLC, HMI, frekvensomriktare</li><li><strong>Konfigurera nätverk</strong> - IP-adresser och Profinet</li><li><strong>Börja programmera</strong> - Skapa OB, FB, FC</li></ol><p>Se nästa avsnitt: <a href="./lagg-till-enheter.html">Lägg till enheter</a></p><h2 id="resurser-och-videotutorials" tabindex="-1">Resurser och videotutorials <a class="header-anchor" href="#resurser-och-videotutorials" aria-label="Permalink to &quot;Resurser och videotutorials&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/109772803" target="_blank" rel="noreferrer">TIA Portal: Creating a Project</a> - Siemens guide</li><li><a href="https://support.industry.siemens.com/cs/document/109476369" target="_blank" rel="noreferrer">TIA Portal Getting Started</a> - Easy Book</li></ul><h3 id="video-tutorials" tabindex="-1">Video-tutorials <a class="header-anchor" href="#video-tutorials" aria-label="Permalink to &quot;Video-tutorials&quot;">​</a></h3><ul><li>Sök på YouTube: &quot;TIA Portal create new project tutorial&quot;</li><li>Rekommenderad: &quot;TIA Portal V18 - First Steps&quot; på Siemens YouTube-kanal</li></ul><div class="info custom-block"><p class="custom-block-title">Tips för nybörjare</p><p>Spara projektet ofta med <code>Ctrl+S</code>. TIA Portal kan krascha vid stora projekt, så regelbunden sparande är viktigt!</p></div>`,42)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
